public class HistoryTypeOracle62 {
 public static String snapshot(){
  Map<String,Object> out=new Map<String,Object>();
  Map<String,Schema.SObjectType> allTypes=Schema.getGlobalDescribe();
  out.put('enabledVisible',allTypes.containsKey('TrackedParcel__History'));
  out.put('disabledVisible',allTypes.containsKey('PlainParcel__History'));
  Schema.DescribeSObjectResult obj=TrackedParcel__History.SObjectType.getDescribe();
  out.put('name',obj.getName());out.put('label',obj.getLabel());out.put('pluralLabel',obj.getLabelPlural());
  out.put('createable',obj.isCreateable());out.put('updateable',obj.isUpdateable());out.put('deletable',obj.isDeletable());out.put('queryable',obj.isQueryable());
  Map<String,Object> fields=new Map<String,Object>();
  for(String name:obj.fields.getMap().keySet()){
   Schema.DescribeFieldResult field=obj.fields.getMap().get(name).getDescribe();
   List<String> refs=new List<String>();for(Schema.SObjectType ref:field.getReferenceTo())refs.add(ref.getDescribe().getName());
   fields.put(name.toLowerCase(),new Map<String,Object>{'type'=>String.valueOf(field.getType()),'createable'=>field.isCreateable(),'updateable'=>field.isUpdateable(),'nillable'=>field.isNillable(),'defaultedOnCreate'=>field.isDefaultedOnCreate(),'relationshipName'=>field.getRelationshipName(),'referenceTo'=>refs});
  }
  out.put('fields',fields);
  TrackedParcel__History item=new TrackedParcel__History(Field='Revision__c',ParentId=null);
  SObject raw=item;List<SObject> records=new List<TrackedParcel__History>{item};
  out.put('constructedField',item.Field);out.put('sobjectName',raw.getSObjectType().getDescribe().getName());out.put('sobjectListSize',records.size());
  return JSON.serialize(out);
 }
}

