public class HistoryInsertOracle62 { public static String snapshot(){Map<String,Object> out=new Map<String,Object>();
  TrackedParcel__c parent=new TrackedParcel__c(Name='Owned specimen',Revision__c='one');Database.insert(parent,AccessLevel.SYSTEM_MODE);
  try {
   TrackedParcel__History item=new TrackedParcel__History(ParentId=parent.Id,Field='Revision__c');Database.insert(item,AccessLevel.SYSTEM_MODE);
   List<TrackedParcel__History> rows=[SELECT Id,ParentId,Field FROM TrackedParcel__History WHERE ParentId=:parent.Id];
   out.put('insertAccepted',true);out.put('queriedRows',rows.size());out.put('storedField',rows.isEmpty()?null:rows[0].Field);out.put('parentMatches',rows.isEmpty()?false:rows[0].ParentId==parent.Id);
  }catch(Exception e){out.put('insertAccepted',false);out.put('errorType',e.getTypeName());out.put('errorMessage',e.getMessage());}
  return JSON.serialize(out);}}

