@IsTest private class HistoryRequiredObserved64{@IsTest static void observed(){
 TrackedParcel__c parent=new TrackedParcel__c(Name='Owned required control');Database.insert(parent,AccessLevel.SYSTEM_MODE);
 List<TrackedParcel__History> inputs=new List<TrackedParcel__History>{new TrackedParcel__History(Field='Revision__c'),new TrackedParcel__History(ParentId=parent.Id)};
 Map<String,Object> out=new Map<String,Object>();Integer n=0;
 for(TrackedParcel__History item:inputs){try{Database.SaveResult sr=Database.insert(item,false,AccessLevel.SYSTEM_MODE);List<String> fields=new List<String>();String code=null;String message=null;if(!sr.isSuccess()){code=String.valueOf(sr.getErrors()[0].getStatusCode());message=sr.getErrors()[0].getMessage();fields=sr.getErrors()[0].getFields();}out.put('case'+n,new Map<String,Object>{'accepted'=>sr.isSuccess(),'code'=>code,'fields'=>fields,'message'=>message});}catch(Exception e){out.put('case'+n,new Map<String,Object>{'type'=>e.getTypeName(),'message'=>e.getMessage()});}n++;}
 System.assert(false,'HISTORY_REQUIRED|'+JSON.serialize(out));}}
